style.css:
/* Thiết lập không gian nền thủy mặc trầm ấm */
html, body {
  margin: 0 !important;
  padding: 0 !important;
  min-height: 100vh !important;
  background-color: #0d0f12 !important;
  position: relative !important;
  overflow-x: hidden !important;
}

/* Lớp 1: Song Long Chầu Thái Cực - Thần Long ngự giữa mây trời */
body::before {
  content: "";
  position: fixed;
  top: 50%;
  left: 50%;
  width: 90vw;
  max-width: 1200px;
  height: 85vh;
  transform: translate(-50%, -50%);
  background-image: url("https://i.pinimg.com/736x/50/74/57/507457f3f3bc345c3b264e7442b61fbf.jpg");
  background-repeat: no-repeat;
  background-position: center center;
  background-size: contain;
  z-index: -2;
  pointer-events: none;
  /* Hiệu ứng Long Khí tụ tán (Thở theo nhịp điệu phong thủy) */
  animation: easternDragonChi 5s ease-in-out infinite alternate;
}

/* Lớp 2: Vòng Càn Khôn Thái Cực bao quanh tâm điểm âm dương */
body::after {
  content: "";
  position: fixed;
  top: 50%;
  left: 50%;
  width: 530px;
  height: 530px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  /* Vòng kim liên ánh vàng phong thủy */
  border: 1.5px solid rgba(230, 195, 92, 0.45);
  box-shadow: 
    0 0 25px rgba(212, 175, 55, 0.35),
    inset 0 0 35px rgba(255, 255, 255, 0.15);
  z-index: -1;
  pointer-events: none;
  animation: canKhonRotate 45s linear infinite;
}

/* Chuyển động Long Khí - Thần Long phát xuất kim quang và linh khí */
@keyframes easternDragonChi {
  0% {
    filter: drop-shadow(0 0 12px rgba(218, 165, 32, 0.35))
            drop-shadow(0 0 30px rgba(255, 250, 240, 0.2))
            contrast(102%) brightness(0.96);
    transform: translate(-50%, -50%) scale(0.995);
  }
  50% {
    filter: drop-shadow(0 0 35px rgba(212, 175, 55, 0.65))
            drop-shadow(0 0 60px rgba(240, 230, 140, 0.4))
            contrast(110%) brightness(1.04);
  }
  100% {
    filter: drop-shadow(0 0 50px rgba(255, 215, 0, 0.8))
            drop-shadow(0 0 85px rgba(255, 255, 255, 0.45))
            contrast(115%) brightness(1.08);
    transform: translate(-50%, -50%) scale(1.008);
  }
}

/* Vòng càn khôn bát quái xoay vận hành nhật nguyệt */
@keyframes canKhonRotate {
  from {
    transform: translate(-50%, -50%) rotate(0deg);
  }
  to {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}
